INSERT INTO flash_sale_activity (activity_name, dish_id, sale_price, stock, available_stock, limit_per_user, start_time, end_time, status, create_time, update_time) SELECT '当季西瓜限时鲜享', d.id, 29.90, 60, 60, 1, NOW() - INTERVAL 1 HOUR, NOW() + INTERVAL 7 DAY, 1, NOW(), NOW() FROM dish d WHERE d.name = '西瓜' AND NOT EXISTS (SELECT 1 FROM flash_sale_activity old WHERE old.activity_name = '当季西瓜限时鲜享' AND old.dish_id = d.id);
INSERT INTO flash_sale_activity (activity_name, dish_id, sale_price, stock, available_stock, limit_per_user, start_time, end_time, status, create_time, update_time) SELECT '鲜切牛腩限时鲜享', d.id, 32.90, 40, 40, 1, NOW() - INTERVAL 1 HOUR, NOW() + INTERVAL 7 DAY, 1, NOW(), NOW() FROM dish d WHERE d.name = '牛腩' AND NOT EXISTS (SELECT 1 FROM flash_sale_activity old WHERE old.activity_name = '鲜切牛腩限时鲜享' AND old.dish_id = d.id);
INSERT INTO flash_sale_activity (activity_name, dish_id, sale_price, stock, available_stock, limit_per_user, start_time, end_time, status, create_time, update_time) SELECT '鲜活黄骨鱼限时鲜享', d.id, 22.90, 35, 35, 1, NOW() - INTERVAL 1 HOUR, NOW() + INTERVAL 7 DAY, 1, NOW(), NOW() FROM dish d WHERE d.name = '黄骨鱼' AND NOT EXISTS (SELECT 1 FROM flash_sale_activity old WHERE old.activity_name = '鲜活黄骨鱼限时鲜享' AND old.dish_id = d.id);
